import sys
input = sys.stdin.read

def solve():
    s = input().strip()
    target = "abcdefghijklmnopqrstuvwxyz"
    t_index = 0
    s = list(s)

    for i in range(len(s)):
        if t_index < len(target) and s[i] <= target[t_index]:
            s[i] = target[t_index]
            t_index += 1

    if t_index == len(target):
        print("".join(s))
    else:
        print("-1")

solve()

