data = input().split()

s = data[0]

result = []
current_char = 'a'
for char in s:
    if ord(char) <= ord(current_char):
        result.append(current_char)
        if current_char != 'z':
            current_char = chr(ord(current_char) + 1)
    if current_char == 'z':
        break

if len(result) == 26:
    print(''.join(result))
else:
    print(-1)

